clear;
clc;
close all;

%% =========================
% READ GEO FILE
%% =========================

filename = 'GSE33075_series_matrix.txt';

fid = fopen(filename);

line = '';

while ~contains(line,'!series_matrix_table_begin')

    line = fgetl(fid);

end

% Read header
header = fgetl(fid);

%% =========================
% READ DATA TABLE
%% =========================

raw = textscan(fid,...
'%s %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f %f',...
'Delimiter','\t');

fclose(fid);

%% =========================
% GENE IDS
%% =========================

gene_ids = raw{1};

%% =========================
% EXPRESSION MATRIX
%% =========================

data = cell2mat(raw(2:end));

%% =========================
% GROUPS
%% =========================

% Diagnosis (CML)
CML = data(:,1:10);

% Treated
Treated = data(:,11:18);

% Healthy
Healthy = data(:,19:27);

%% =========================
% AVERAGES
%% =========================

CML_avg = mean(CML,2);

Treated_avg = mean(Treated,2);

Healthy_avg = mean(Healthy,2);

%% =========================
% DIFFERENCE
%% =========================

change = Treated_avg - CML_avg;

%% =========================
% SORT GENES
%% =========================

[sorted_change,idx] = sort(change);

sorted_genes = gene_ids(idx);

%% =========================
% TOP DOWNREGULATED GENES
%% =========================

disp('Top Downregulated Genes'); %[output:9692dbbe]

for i = 1:10 %[output:group:5ecd8237]

    fprintf('%s  Change = %.3f\n',... %[output:8589e543]
        sorted_genes{i},... %[output:8589e543]
        sorted_change(i)); %[output:8589e543]

end %[output:group:5ecd8237]

%% =========================
% BAR PLOT EXAMPLE
%% =========================

gene_index = idx(1);

example_gene = data(gene_index,:);

figure; %[output:80bf3a21]

bar(example_gene) %[output:80bf3a21]

xlabel('Samples') %[output:80bf3a21]

ylabel('Expression') %[output:80bf3a21]

title(['Gene: ',sorted_genes{1}]) %[output:80bf3a21]

grid on %[output:80bf3a21]

